command:
cat > check.js <<'EOF'
const fs = require('fs');
const path = require('path');

const DEFAULTS = { port: 3000, host: '127.0.0.1' };

const inPath = path.join(__dirname, 'config.json');
const outPath = path.join(__dirname, 'config.out.json');

let config = {};
try {
  config = JSON.parse(fs.readFileSync(inPath, 'utf8'));
} catch (err) {
  if (err.code !== 'ENOENT') throw err;
}

const result = { ...DEFAULTS, ...config };
fs.writeFileSync(outPath, JSON.stringify(result, null, 2) + '\n');
console.log('wrote', outPath, result);
EOF
node check.js && cat config.out.json

